-- Data migration, written by hand. The seeded monogram headshots were SVG, and SVG
-- is a scriptable document: the security pass narrowed uploads and every route that
-- serves them to PNG, JPEG, WebP, and GIF, so these had to become raster or stop
-- rendering. Same pictures, same keys apart from the extension. A fresh install has
-- none of these rows (seed.sql ships PNGs already) and this does nothing there.
INSERT OR REPLACE INTO blobs (key,data,content_type,size,created_at) SELECT 'headshot-seed/1.png',X'','image/png',1265,1786305600 WHERE EXISTS (SELECT 1 FROM blobs WHERE key='headshot-seed/1.svg');
--> statement-breakpoint
UPDATE contacts SET headshot_blob_key='headshot-seed/1.png' WHERE headshot_blob_key='headshot-seed/1.svg';
--> statement-breakpoint
UPDATE file_uploads SET blob_key='headshot-seed/1.png', content_type='image/png' WHERE blob_key='headshot-seed/1.svg';
--> statement-breakpoint
DELETE FROM blobs WHERE key='headshot-seed/1.svg';
--> statement-breakpoint
